'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// caret zero-major
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);

// backtracking must undo constraints of abandoned choice
const reg1 = {
  a: { '2.0.0': { b: '^2.0.0', c: '^1.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '2.0.0': { c: '^2.0.0' } },
  c: { '2.0.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg1, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// cycle
const reg2 = { x: { '1.0.0': { y: '1.0.0' } }, y: { '1.0.0': { x: '1.0.0' } } };
assert.deepEqual(resolve(reg2, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// long chain (no stack/iteration cap)
const reg3 = {};
const N = 20000;
for (let i = 0; i < N; i++) reg3['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(reg3, { p0: '*' })).length, N);

// deep missing package unsatisfiable quickly despite wide choices
const reg4 = { z: { '1.0.0': { missing: '*' } } };
const root4 = {};
for (let i = 0; i < 10; i++) { reg4['w' + i] = { '1.0.0': {}, '2.0.0': {} }; root4['w' + i] = '*'; }
root4.z = '*';
assert.equal(resolve(reg4, root4), null);

// eager validation of unreachable entries
assert.throws(() => resolve({ q: { '01.0.0': {} } }, {}), TypeError);
assert.deepEqual(resolve({}, {}), {});
console.log('smoke ok');
